window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-30851394be0debd6"]={"versions": [{"id": "FIG-30851394be0debd6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifesterweiterungskonzepts im Kontext des Intrusion Detection System Manager (IdsM). Dargestellt ist das Metamodell für das Mapping von Sicherheitsereignissen (<code>SecurityEventMapping</code>) zwischen Softwarekomponenten-Ports und Sicherheitsereignisdefinitionen innerhalb einer Prozessausführungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SecurityEventMapping</strong> (Spezialisierung von <code>UploadablePackageElement</code>): Zentrales Mappingelement mit Attribut <code>+ id: PositiveInteger [0..1]</code>. Besitzt Aggregationen bzw. Referenzen:</li>\n<li>Aggregation <code>+reportingPortPrototype</code> [0..1] zu <code>RPortPrototypeInExecutableInstanceRef</code>.</li>\n<li>Zusammengesetzte Aggregation (Aggregation über <code>IdsmModuleInstantiation</code> / <code>IdsPlatformInstantiation</code>) als <code>+reportableSecurityEvent</code> [0..*] mit Stereotyp <code>«atpSplitable»</code>.</li>\n<li>Assoziation <code>+process</code> [0..1] zu <code>Process</code> (Spezialisierung von <code>AbstractExecutionContext</code>).</li>\n<li>Assoziation <code>+securityEvent</code> [0..*] zu <code>SecurityEventDefinition</code> mit Stereotypen <code>«atpSplitable,atpUriDef»</code>.</li>\n<li>Abgeleitete Instanzreferenz <code>+reportingPortPrototype</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototypeInExecutableInstanceRef</strong> (Spezialisierung von <code>AbstractPortPrototypeInExecutableInstanceRef</code>):</li>\n<li>Assoziation <code>+targetRPortPrototype</code> [1] {redefines targetPortPrototype} zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototype</strong> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>):</li>\n<li>Assoziation <code>+requiredInterface</code> [0..1] {redefines atpType} mit Stereotyp <code>«isOfType»</code> zu <code>PortInterface</code>.</li>\n<li><strong>PortInterface</strong> (Klassenhierarchie: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>):</li>\n<li>Generalisierungsbasis für <code>SecurityEventReportInterface</code>.</li>\n<li><strong>SecurityEventDefinition</strong> (Spezialisierung von <code>IdsCommonElement</code>): Definiert Sicherheitsereignisse mit Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li><strong>IdsmModuleInstantiation</strong> (Spezialisierung von <code>IdsPlatformInstantiation</code>): Plattforminstanziierung des IdsM-Moduls.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es definiert die deklarative Konfigurations- und Modellierungsstruktur für das Binden von R-Ports ausführbarer Einheiten an Sicherheitsereignis-Definitionen des IdsM zur Laufzeitüberwachung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>SecurityEventMapping</code> ordnet über <code>RPortPrototypeInExecutableInstanceRef</code> genau einen Zielport (<code>targetRPortPrototype</code> mit Kardinalität 1) einem spezifischen Prozess (<code>Process</code>) und mehreren Sicherheitsereignissen (<code>SecurityEventDefinition</code>, Kardinalität 0..*) zu.</li>\n<li>Die Beziehung <code>+reportingPortPrototype</code> wird modellseitig als Instanzreferenz (<code>«instanceRef,atpUriDef»</code>) aufgelöst.</li>\n<li>Port-Typisierung verlangt die typkonforme Ausprägung über <code>SecurityEventReportInterface</code>.</li>\n<li>Splitbarkeit und URI-Referenzierung sind über <code>«atpSplitable»</code> und <code>«atpUriDef»</code> für die Modell-Zusammenführung über Teilmodelle hinweg spezifiziert.</li>\n</ul>"}, {"id": "FIG-bd5303f92b5eed1a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifesterweiterungskonzepts im Kontext des Intrusion Detection System Manager (IdsM). Dargestellt ist das Metamodell für das Mapping von Sicherheitsereignissen (<code>SecurityEventMapping</code>) zwischen Softwarekomponenten-Ports und Sicherheitsereignisdefinitionen innerhalb einer Prozessausführungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SecurityEventMapping</strong> (Spezialisierung von <code>UploadablePackageElement</code>): Zentrales Mappingelement mit Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li>Aggregation <code>+reportingPortPrototype</code> [0..1] mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototypeInExecutableInstanceRef</code>.</li>\n<li>Übergeordnete Aggregation <code>+reportableSecurityEvent</code> [0..*] mit Stereotyp <code>«atpSplitable»</code> ausgehend von <code>IdsmModuleInstantiation</code> / <code>IdsPlatformInstantiation</code>.</li>\n<li>Assoziation <code>+process</code> [0..1] zu <code>Process</code> (Spezialisierung von <code>AbstractExecutionContext</code>).</li>\n<li>Assoziation <code>+securityEvent</code> [0..*] zu <code>SecurityEventDefinition</code> mit Stereotypen <code>«atpSplitable,atpUriDef»</code>.</li>\n<li>Abgeleitete Instanzreferenz <code>+reportingPortPrototype</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototypeInExecutableInstanceRef</strong> (Spezialisierung von <code>AbstractPortPrototypeInExecutableInstanceRef</code>):</li>\n<li>Assoziation <code>+targetRPortPrototype</code> [0..1] {redefines targetPortPrototype} mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototype</strong> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>):</li>\n<li>Assoziation <code>+requiredInterface</code> [0..1] {redefines atpType} mit Stereotyp <code>«isOfType»</code> zu <code>PortInterface</code>.</li>\n<li><strong>PortInterface</strong> (Klassenhierarchie: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>):</li>\n<li>Generalisierungsbasis für <code>SecurityEventReportInterface</code>.</li>\n<li><strong>SecurityEventDefinition</strong> (Spezialisierung von <code>IdsCommonElement</code>): Beinhaltet Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li><strong>IdsmModuleInstantiation</strong> (Spezialisierung von <code>IdsPlatformInstantiation</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es definiert die deklarative Konfigurations- und Modellierungsstruktur für das Binden von R-Ports ausführbarer Einheiten an Sicherheitsereignis-Definitionen des IdsM zur Laufzeitüberwachung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Ziel eines <code>RPortPrototypeInExecutableInstanceRef</code> ist optional (<code>+targetRPortPrototype</code> besitzt Kardinalität 0..1) und trägt den Stereotyp <code>«atpUriDef»</code>.</li>\n<li>Die Aggregation <code>+reportingPortPrototype</code> vom <code>SecurityEventMapping</code> auf <code>RPortPrototypeInExecutableInstanceRef</code> ist explizit als URI-Definition (<code>«atpUriDef»</code>) deklariert.</li>\n<li>Modellierungsregeln bezüglich Splitbarkeit und Instanzauflösung bleiben für die beteiligten Manifest-Elemente verbindlich.</li>\n</ul>"}, {"id": "FIG-8c7bfeb4650d1f72", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifesterweiterungskonzepts im Kontext des Intrusion Detection System Manager (IdsM). Dargestellt ist das Metamodell für das Mapping von Sicherheitsereignissen (<code>SecurityEventMapping</code>) zwischen Softwarekomponenten-Ports und Sicherheitsereignisdefinitionen innerhalb einer Prozessausführungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SecurityEventMapping</strong> (Spezialisierung von <code>UploadablePackageElement</code>): Zentrales Mappingelement mit Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li>Aggregation <code>+reportingPortPrototype</code> [0..1] mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototypeInExecutableInstanceRef</code>.</li>\n<li>Übergeordnete Aggregation <code>+reportableSecurityEvent</code> [0..*] mit Stereotyp <code>«atpSplitable»</code> ausgehend von <code>IdsmModuleInstantiation</code> / <code>IdsPlatformInstantiation</code>.</li>\n<li>Assoziation <code>+process</code> [0..1] zu <code>Process</code> (Spezialisierung von <code>AbstractExecutionContext</code>).</li>\n<li>Assoziation <code>+securityEvent</code> [0..*] zu <code>SecurityEventDefinition</code> mit Stereotypen <code>«atpSplitable,atpUriDef»</code>.</li>\n<li>Abgeleitete Instanzreferenz <code>+reportingPortPrototype</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototypeInExecutableInstanceRef</strong> (Spezialisierung von <code>AbstractPortPrototypeInExecutableInstanceRef</code>):</li>\n<li>Assoziation <code>+targetRPortPrototype</code> [0..1] {redefines targetPortPrototype} mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototype</strong> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>):</li>\n<li>Assoziation <code>+requiredInterface</code> [0..1] {redefines atpType} mit Stereotyp <code>«isOfType»</code> zu <code>PortInterface</code>.</li>\n<li><strong>PortInterface</strong> (Klassenhierarchie: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>):</li>\n<li>Generalisierungsbasis für <code>SecurityEventReportInterface</code>.</li>\n<li><strong>SecurityEventDefinition</strong> (Spezialisierung von <code>IdsCommonElement</code>): Beinhaltet Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li><strong>IdsmModuleInstantiation</strong> (Spezialisierung von <code>IdsPlatformInstantiation</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es definiert die deklarative Konfigurations- und Modellierungsstruktur für das Binden von R-Ports ausführbarer Einheiten an Sicherheitsereignis-Definitionen des IdsM zur Laufzeitüberwachung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Ziel eines <code>RPortPrototypeInExecutableInstanceRef</code> ist optional (<code>+targetRPortPrototype</code> besitzt Kardinalität 0..1) und trägt den Stereotyp <code>«atpUriDef»</code>.</li>\n<li>Die Aggregation <code>+reportingPortPrototype</code> vom <code>SecurityEventMapping</code> auf <code>RPortPrototypeInExecutableInstanceRef</code> ist explizit als URI-Definition (<code>«atpUriDef»</code>) deklariert.</li>\n<li>Modellierungsregeln bezüglich Splitbarkeit und Instanzauflösung bleiben für die beteiligten Manifest-Elemente verbindlich.</li>\n</ul>"}, {"id": "FIG-52ba7b9047e9e18c", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifesterweiterungskonzepts im Kontext des Intrusion Detection System Manager (IdsM). Dargestellt ist das Metamodell für das Mapping von Sicherheitsereignissen (<code>SecurityEventMapping</code>) zwischen Softwarekomponenten-Ports und Sicherheitsereignisdefinitionen innerhalb einer Prozessausführungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SecurityEventMapping</strong> (Spezialisierung von <code>UploadableDeploymentElement</code>): Mappingelement mit Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li>Aggregation <code>+reportingPortPrototype</code> [0..1] mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototypeInExecutableInstanceRef</code>.</li>\n<li>Übergeordnete Aggregation <code>+reportableSecurityEvent</code> [0..*] mit Stereotyp <code>«atpSplitable»</code> ausgehend von <code>IdsmModuleInstantiation</code> / <code>IdsPlatformInstantiation</code>.</li>\n<li>Assoziation <code>+process</code> [0..1] zu <code>Process</code> (<code>AbstractExecutionContext</code>).</li>\n<li>Assoziation <code>+securityEvent</code> [0..*] mit Stereotypen <code>«atpSplitable,atpUriDef»</code> zu <code>SecurityEventDefinition</code>.</li>\n<li>Instanzreferenz <code>+reportingPortPrototype</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototypeInExecutableInstanceRef</strong> (<code>AbstractPortPrototypeInExecutableInstanceRef</code>):</li>\n<li>Assoziation <code>+targetRPortPrototype</code> [0..1] {redefines targetPortPrototype} mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototype</strong> (<code>AbstractRequiredPortPrototype</code>):</li>\n<li>Assoziation <code>+requiredInterface</code> [0..1] {redefines atpType} mit Stereotyp <code>«isOfType»</code> zu <code>PortInterface</code>.</li>\n<li><strong>PortInterface</strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>):</li>\n<li>Generalisierungsbasis für <code>IdsmAbstractPortInterface</code>.</li>\n<li><strong>IdsmAbstractPortInterface</strong>: Abstrakte Schnittstellendefinition, spezialisiert <code>PortInterface</code> und fungiert als Basisklasse für <code>SecurityEventReportInterface</code>.</li>\n<li><strong>SecurityEventReportInterface</strong>: Spezialisiert <code>IdsmAbstractPortInterface</code>.</li>\n<li><strong>SecurityEventDefinition</strong> (<code>IdsCommonElement</code>): Enthält Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li><strong>IdsmModuleInstantiation</strong> (<code>IdsPlatformInstantiation</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es definiert die deklarative Konfigurations- und Modellierungsstruktur für das Binden von R-Ports ausführbarer Einheiten an Sicherheitsereignis-Definitionen des IdsM zur Laufzeitüberwachung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>SecurityEventMapping</code> erbt als <code>UploadableDeploymentElement</code> aus dem Deployment-Metamodell.</li>\n<li><code>SecurityEventReportInterface</code> leitet sich nun von der Zwischenabstraktion <code>IdsmAbstractPortInterface</code> ab, wodurch eine typologische Vereinheitlichung IdsM-spezifischer Schnittstellen auf <code>PortInterface</code>-Ebene vorgenommen wird.</li>\n<li>Die Kardinalitäten für <code>targetRPortPrototype</code> (0..1) und <code>reportingPortPrototype</code> (0..1) bleiben gewahrt.</li>\n</ul>"}, {"id": "FIG-18302f27d5282d3d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifesterweiterungskonzepts im Kontext des Intrusion Detection System Manager (IdsM). Dargestellt ist das Metamodell für das Mapping von Sicherheitsereignissen (<code>SecurityEventMapping</code>) zwischen Softwarekomponenten-Ports und Sicherheitsereignisdefinitionen innerhalb einer Prozessausführungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SecurityEventMapping</strong> (Spezialisierung von <code>UploadableDeploymentElement</code>): Zentrales Mappingelement ohne eigene Attribute.</li>\n<li>Aggregation <code>+reportingPortPrototype</code> [0..1] mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototypeInExecutableInstanceRef</code>.</li>\n<li>Übergeordnete Aggregation <code>+reportableSecurityEvent</code> [0..*] mit Stereotyp <code>«atpSplitable»</code> ausgehend von <code>IdsmModuleInstantiation</code> / <code>IdsPlatformInstantiation</code>.</li>\n<li>Assoziation <code>+process</code> [0..1] horizontal geführt zu <code>Process</code> (<code>AbstractExecutionContext</code>).</li>\n<li>Assoziation <code>+securityEvent</code> [0..1] zu <code>SecurityEventDefinition</code>.</li>\n<li>Instanzreferenz <code>+reportingPortPrototype</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototypeInExecutableInstanceRef</strong> (<code>AbstractPortPrototypeInExecutableInstanceRef</code>):</li>\n<li>Assoziation <code>+targetRPortPrototype</code> [0..1] {redefines targetPortPrototype} mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototype</strong> (<code>AbstractRequiredPortPrototype</code>):</li>\n<li>Assoziation <code>+requiredInterface</code> [0..1] {redefines atpType} mit Stereotyp <code>«isOfType»</code> zu <code>PortInterface</code>.</li>\n<li><strong>PortInterface</strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>):</li>\n<li>Basisklasse für <code>IdsmAbstractPortInterface</code>.</li>\n<li><strong>IdsmAbstractPortInterface</strong>: Abstrakte Zwischenklasse, Generalisierungsbasis für <code>SecurityEventReportInterface</code>.</li>\n<li><strong>SecurityEventReportInterface</strong>: Spezialisierung von <code>IdsmAbstractPortInterface</code>.</li>\n<li><strong>SecurityEventDefinition</strong> (<code>IdsCommonElement</code>): Enthält Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li><strong>IdsmModuleInstantiation</strong> (<code>IdsPlatformInstantiation</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es definiert die deklarative Konfigurations- und Modellierungsstruktur für das Binden von R-Ports ausführbarer Einheiten an Sicherheitsereignis-Definitionen des IdsM zur Laufzeitüberwachung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>SecurityEventMapping</code> besitzt kein eigenes <code>id</code>-Attribut mehr; die Identifikation erfolgt über die übergeordneten Metaklassen bzw. Referenzen.</li>\n<li>Ein <code>SecurityEventMapping</code> bindet nun an höchstens ein einzelnes <code>SecurityEventDefinition</code>-Element (<code>+securityEvent</code> besitzt Kardinalität 0..1 statt 0..*); die Stereotype <code>«atpSplitable,atpUriDef»</code> an dieser Relation entfallen.</li>\n<li>Die Zuordnung zu einem <code>Process</code> ist weiterhin optional (<code>0..1</code>).</li>\n</ul>"}, {"id": "FIG-2f7ed2ceb920b921", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifesterweiterungskonzepts im Kontext des Intrusion Detection System Manager (IdsM). Dargestellt ist das Metamodell für das Mapping von Sicherheitsereignissen (<code>SecurityEventMapping</code>) zwischen Softwarekomponenten-Ports und Sicherheitsereignisdefinitionen innerhalb einer Prozessausführungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SecurityEventMapping</strong> (Spezialisierung von <code>UploadableDeploymentElement</code>): Zentrales Mappingelement ohne eigene Attribute.</li>\n<li>Aggregation <code>+reportingPortPrototype</code> [0..1] mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototypeInExecutableInstanceRef</code>.</li>\n<li>Übergeordnete Aggregation <code>+reportableSecurityEvent</code> [0..*] mit Stereotyp <code>«atpSplitable»</code> ausgehend von <code>IdsmModuleInstantiation</code> / <code>IdsPlatformInstantiation</code>.</li>\n<li>Assoziation <code>+process</code> [0..1] horizontal geführt zu <code>Process</code> (<code>AbstractExecutionContext</code>).</li>\n<li>Assoziation <code>+securityEvent</code> [0..1] zu <code>SecurityEventDefinition</code>.</li>\n<li>Instanzreferenz <code>+reportingPortPrototype</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototypeInExecutableInstanceRef</strong> (<code>AbstractPortPrototypeInExecutableInstanceRef</code>):</li>\n<li>Assoziation <code>+targetRPortPrototype</code> [0..1] {redefines targetPortPrototype} mit Stereotyp <code>«atpUriDef»</code> zu <code>RPortPrototype</code>.</li>\n<li><strong>RPortPrototype</strong> (<code>AbstractRequiredPortPrototype</code>):</li>\n<li>Assoziation <code>+requiredInterface</code> [0..1] {redefines atpType} mit Stereotyp <code>«isOfType»</code> zu <code>PortInterface</code>.</li>\n<li><strong>PortInterface</strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>):</li>\n<li>Basisklasse für <code>IdsmAbstractPortInterface</code>.</li>\n<li><strong>IdsmAbstractPortInterface</strong>: Abstrakte Zwischenklasse, Generalisierungsbasis für <code>SecurityEventReportInterface</code>.</li>\n<li><strong>SecurityEventReportInterface</strong>: Spezialisierung von <code>IdsmAbstractPortInterface</code>.</li>\n<li><strong>SecurityEventDefinition</strong> (<code>IdsCommonElement</code>): Enthält Attribut <code>+ id: PositiveInteger [0..1]</code>.</li>\n<li><strong>IdsmModuleInstantiation</strong> (<code>IdsPlatformInstantiation</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es definiert die deklarative Konfigurations- und Modellierungsstruktur für das Binden von R-Ports ausführbarer Einheiten an Sicherheitsereignis-Definitionen des IdsM zur Laufzeitüberwachung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>SecurityEventMapping</code> besitzt kein eigenes <code>id</code>-Attribut mehr; die Identifikation erfolgt über die übergeordneten Metaklassen bzw. Referenzen.</li>\n<li>Ein <code>SecurityEventMapping</code> bindet nun an höchstens ein einzelnes <code>SecurityEventDefinition</code>-Element (<code>+securityEvent</code> besitzt Kardinalität 0..1 statt 0..*); die Stereotype <code>«atpSplitable,atpUriDef»</code> an dieser Relation entfallen.</li>\n<li>Die Zuordnung zu einem <code>Process</code> ist weiterhin optional (<code>0..1</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-30851394be0debd6", "to": "FIG-bd5303f92b5eed1a", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>RPortPrototypeInExecutableInstanceRef</code>: Kardinalität der Assoziationsrolle <code>+targetRPortPrototype</code> (redefines targetPortPrototype) auf <code>RPortPrototype</code> von <code>1</code> auf <code>0..1</code> geändert; Stereotyp <code>«atpUriDef»</code> ergänzt.</li>\n<li><code>SecurityEventMapping</code>: Assoziation <code>+reportingPortPrototype</code> auf <code>RPortPrototypeInExecutableInstanceRef</code> mit Stereotyp <code>«atpUriDef»</code> versehen.</li>\n<li>Layout: Position von <code>RPortPrototypeInExecutableInstanceRef</code> von oben links in die Mitte zwischen die Klassen verschoben.</li>\n</ul>"}, {"from": "FIG-bd5303f92b5eed1a", "to": "FIG-8c7bfeb4650d1f72", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8c7bfeb4650d1f72", "to": "FIG-52ba7b9047e9e18c", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SecurityEventMapping</code>: Basiselement-Klassifikation von <code>UploadablePackageElement</code> auf <code>UploadableDeploymentElement</code> geändert.</li>\n<li><code>SecurityEventReportInterface</code>: Neue abstrakte Zwischenklasse <code>IdsmAbstractPortInterface</code> eingeführt, die von <code>PortInterface</code> erbt und als Basis für <code>SecurityEventReportInterface</code> dient.</li>\n</ul>"}, {"from": "FIG-52ba7b9047e9e18c", "to": "FIG-18302f27d5282d3d", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SecurityEventMapping</code>: Attribut <code>+ id: PositiveInteger [0..1]</code> entfernt.</li>\n<li><code>SecurityEventMapping</code>: Kardinalität der Aggregation <code>+securityEvent</code> zu <code>SecurityEventDefinition</code> von <code>0..*</code> auf <code>0..1</code> reduziert; Stereotyp <code>«atpSplitable,atpUriDef»</code> entfernt.</li>\n<li><code>SecurityEventMapping</code>: Assoziation <code>+process</code> (Kardinalität <code>0..1</code>) zu <code>Process</code> nach rechts ausgelagert statt nach unten geführt.</li>\n</ul>"}, {"from": "FIG-18302f27d5282d3d", "to": "FIG-2f7ed2ceb920b921", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
